import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';

export function run(aVal, bVal = '0') {
  const r = spawnSync('/usr/bin/timeout', ['5', EXE, '--a', aVal, '--b', bVal], {
    encoding: 'utf8',
  });
  return {
    code: r.status,
    out: r.stdout ?? '',
    err: r.stderr ?? '',
  };
}

// Classify result: 'ok:<firstline>' or 'invalid:<repr>' or 'other:...'
export function classify(r) {
  if (r.code === 0) {
    // last line is the count for range(a+b); first line is range(a) count
    const lines = r.out.split('\n');
    return { kind: 'ok', line1: lines[0], line8: lines[7] };
  }
  const m = /^.*: error: argument --a: invalid int value: (.*)$/m.exec(r.err);
  if (m) return { kind: 'invalid', repr: m[1] };
  const m2 = /^.*: error: (.*)$/m.exec(r.err);
  if (m2) return { kind: 'error', msg: m2[1] };
  return { kind: 'other', err: r.err, code: r.code };
}

export function probe(label, aVal, bVal = '0') {
  const r = run(aVal, bVal);
  const c = classify(r);
  return { label, input: aVal, ...c, code: r.code };
}

import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test11_executable';
const B = 10; // so line8 = max(a+10,0) -> recovers a for a >= -10

export function run(aVal, bVal = String(B)) {
  const r = spawnSync('/usr/bin/timeout', ['5', EXE, '--a', aVal, '--b', bVal]);
  return { code: r.status, out: r.stdout ?? Buffer.alloc(0), err: r.stderr ?? Buffer.alloc(0) };
}

export function classify(r) {
  const out = r.out.toString('utf8');
  const err = r.err.toString('utf8');
  if (r.code === 0) {
    const lines = out.split('\n');
    const line8 = Number(lines[7]);
    return { kind: 'ACCEPT', value: Number.isFinite(line8) ? line8 - B : '?', line1: lines[0] };
  }
  let m = /error: argument --a: invalid int value: (.*)$/m.exec(err);
  if (m) return { kind: 'INVALID', repr: m[1] };
  m = /error: (.*)$/m.exec(err);
  if (m) return { kind: 'ERR', msg: m[1] };
  return { kind: 'OTHER', code: r.code, err };
}

// human-readable display of the input we sent
export function show(s) {
  let o = '';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (cp === 0x5c) o += '\\\\';
    else if (cp < 0x20 || cp === 0x7f) o += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp < 0x7f) o += ch;
    else o += '<U+' + cp.toString(16).toUpperCase().padStart(4, '0') + '>';
  }
  return o;
}

export function probe(label, aVal) {
  const c = classify(run(aVal));
  return { label, sent: show(aVal), ...c };
}

export function table(rows, cols) {
  const w = cols.map((c) => Math.max(c.length, ...rows.map((r) => String(r[c] ?? '').length)));
  const line = (vals) => vals.map((v, i) => String(v ?? '').padEnd(w[i])).join(' | ');
  const outp = [line(cols), w.map((n) => '-'.repeat(n)).join('-+-')];
  for (const r of rows) outp.push(line(cols.map((c) => r[c])));
  return outp.join('\n');
}

