import { spawnSync } from 'node:child_process';
import { pyRepr } from './predict.mjs';
import { show, table } from './probe.mjs';

const EXE = '/workspace/dataset/test11_executable';
const WS = /\p{White_Space}/u, ND = /\p{Nd}/u;
function ndVal(cp){ let s=cp; while(s>0 && ND.test(String.fromCodePoint(s-1))) s--; return (cp-s)%10; }

// spec-faithful pyInt: returns BigInt or null (ValueError)
function pyInt(str){
  const cps=[...str];
  let i=0,j=cps.length;
  while(i<j && WS.test(cps[i])) i++;
  while(j>i && WS.test(cps[j-1])) j--;
  const t=cps.slice(i,j);
  let k=0,neg=false;
  if(t[0]==='+'||t[0]==='-'){ neg=t[0]==='-'; k=1; }
  if(k>=t.length) return null;
  let digits='',prevDigit=false;
  for(;k<t.length;k++){
    const ch=t[k];
    if(ch==='_'){ if(!prevDigit) return null; if(k+1>=t.length||!ND.test(t[k+1])) return null; prevDigit=false; continue; }
    if(!ND.test(ch)) return null;
    digits+=String(ndVal(ch.codePointAt(0))); prevDigit=true;
  }
  if(!digits) return null;
  const v=BigInt(digits);
  return neg?-v:v;
}

function oracle(v){
  const r=spawnSync('/usr/bin/timeout',['5',EXE,`--a=${v}`,'--b','10']);
  const err=(r.stderr??Buffer.alloc(0)).toString('utf8');
  const out=(r.stdout??Buffer.alloc(0)).toString('utf8');
  if(r.status===0){ const n=Number(out.split('\n')[7]); return {ok:true, val:n-10}; }
  const m=/error: argument --a: invalid int value: (.*)$/m.exec(err);
  if(m) return {ok:false, repr:m[1]};
  return {ok:null, err};
}

const ALPHA=['0','1','5','9','_','+','-',' ','\t',' ','٥','۵','１','\u{1D7DD}','​','﻿','.','x','²','　','\n'];
let mism=[];
let n=0;
for(let t=0;t<320;t++){
  const len=1+Math.floor(Math.random()*4);
  let s='';
  for(let i=0;i<len;i++) s+=ALPHA[Math.floor(Math.random()*ALPHA.length)];
  const mine=pyInt(s);
  const o=oracle(s); n++;
  if(o.ok===null) continue;
  if(o.ok){
    // accepted: compare value (saturates at <= -10)
    const exp = mine===null ? 'REJECT' : (mine+10n<=0n? 'SAT' : String(mine));
    const got = o.val<=-10? 'SAT' : String(o.val);
    if(mine===null || exp!==got) mism.push({sent:show(s),mine:mine===null?'REJECT':String(mine),oracle:'ACCEPT '+got});
  } else {
    const myRepr=pyRepr(s);
    if(mine!==null) mism.push({sent:show(s),mine:'ACCEPT '+mine,oracle:'INVALID '+o.repr});
    else if(myRepr!==o.repr) mism.push({sent:show(s),mine:'repr '+myRepr,oracle:'repr '+o.repr});
  }
}
